// ============================================================================
// Ω-MYTHOS_X10_ENGINE — Cloudflare Worker Entrypoint
// Santander Argentina Macro Oracle + X10 Decision Engine
//
// Routes:
//   GET  /api/macro          → Macro state + staleness + regime + confidence
//   POST /api/x10             → Full X10 allocation (input: capital + mode)
//   GET  /api/regime          → Current regime + history + transition probability
//   GET  /api/backtest-lite   → Simplified backtest with historical scenarios
//
// Hard Constraints:
//   - No Node.js APIs
//   - No in-memory state (KV/D1 only)
//   - Deterministic execution (seeded PRNG)
//   - API keys via wrangler secrets only
// ============================================================================

/// <reference types="@cloudflare/workers-types" />

import { type Env, type MacroResponse, type X10Request, type X10Response, type RegimeResponse, type CapitalRegime, type DataLabel } from './lib/types';
import { fetchMacroState } from './lib/data-fetcher';
import { computeOracle, classifyRegime, computeL1Signals, runX10Engine } from './lib/engine';
import { mulberry32 } from './lib/seeded-rng';

// ============================================================================
// ROUTER
// ============================================================================

export default {
  async fetch(request: Request, env: Env, ctx: ExecutionContext): Promise<Response> {
    const url = new URL(request.url);
    const path = url.pathname;

    // CORS preflight
    if (request.method === 'OPTIONS') {
      return new Response(null, { status: 204, headers: corsHeaders() });
    }

    try {
      // ─── Route matching ───
      if (path === '/api/macro' && request.method === 'GET') {
        return await handleMacro(env, ctx);
      }
      if (path === '/api/x10' && request.method === 'POST') {
        return await handleX10(request, env, ctx);
      }
      if (path === '/api/regime' && request.method === 'GET') {
        return await handleRegime(env, ctx);
      }
      if (path === '/api/backtest-lite' && request.method === 'GET') {
        return await handleBacktestLite(env, url);
      }
      if (path === '/api/health' && request.method === 'GET') {
        return jsonResponse({ status: 'ok', version: 'X10-CF-WORKER-v1.0', timestamp: new Date().toISOString() });
      }

      return jsonResponse({ error: 'Not Found', path }, 404);
    } catch (err) {
      // FAILSAFE: Return safe error response
      const message = err instanceof Error ? err.message : 'Internal server error';
      return jsonResponse({
        error: 'INTERNAL_ERROR',
        message,
        failsafe: 'If API fetch failed, stale cached macro_state should be used',
        timestamp: new Date().toISOString(),
      }, 500);
    }
  },
};

// ============================================================================
// HANDLERS
// ============================================================================

/**
 * GET /api/macro — Current macro state + staleness + regime + oracle
 */
async function handleMacro(env: Env, ctx: ExecutionContext): Promise<Response> {
  const macro = await fetchMacroState(env);
  const { regime, confidence, oracle } = classifyRegime(macro);

  // Build staleness report
  const staleness_report: Record<string, { label: DataLabel; stalenessHours: number }> = {};
  for (const [key, prov] of Object.entries(macro.provenance)) {
    staleness_report[key] = { label: prov.label, stalenessHours: prov.stalenessHours };
  }

  // Log to D1 (non-blocking)
  ctx.waitUntil(logMacroSnapshot(env, macro, regime, confidence));

  const response: MacroResponse = {
    macro_state: macro,
    staleness_report,
    regime,
    confidence: Math.round(confidence * 100) / 100,
    oracle,
    timestamp: new Date().toISOString(),
  };

  return jsonResponse(response);
}

/**
 * POST /api/x10 — Full X10 allocation engine
 * Body: { capital: number, mode: 'CONSERVATIVE' | 'MODERATE' | 'AGGRESSIVE' }
 */
async function handleX10(request: Request, env: Env, ctx: ExecutionContext): Promise<Response> {
  // Parse request body
  let body: X10Request;
  try {
    body = await request.json() as X10Request;
  } catch {
    return jsonResponse({ error: 'Invalid JSON body' }, 400);
  }

  // Validate
  const capital = body.capital || 2000;
  const mode = ['CONSERVATIVE', 'MODERATE', 'AGGRESSIVE'].includes(body.mode) ? body.mode : 'MODERATE';
  if (capital < 100 || capital > 1000000) {
    return jsonResponse({ error: 'Capital must be between 100 and 1,000,000 USD' }, 400);
  }

  // Fetch macro state
  const macro = await fetchMacroState(env);

  // Run X10 engine
  const engineOutput = runX10Engine(macro, mode, capital);

  // Log decision to D1 (non-blocking)
  ctx.waitUntil(logDecision(env, engineOutput, mode, capital));

  const response: X10Response = {
    allocation: engineOutput.portfolio_allocation,
    risk_metrics: engineOutput.risk_metrics,
    confidence: engineOutput.confidence_score,
    stress_scenarios: {
      downside: engineOutput.scenario_downside,
      base: engineOutput.scenario_base,
      upside: engineOutput.scenario_upside,
    },
    x10_directives: engineOutput.x10Directives,
    timestamp: engineOutput.timestamp,
  };

  return jsonResponse(response);
}

/**
 * GET /api/regime — Current regime + history + transition probability
 */
async function handleRegime(env: Env, ctx: ExecutionContext): Promise<Response> {
  const macro = await fetchMacroState(env);
  const { regime, confidence, oracle } = classifyRegime(macro);

  // Get regime history from D1
  let regime_history: { timestamp: string; regime: CapitalRegime; confidence: number }[] = [];
  try {
    const result = await env.ORACLE_DB
      .prepare('SELECT timestamp, regime, confidence FROM regime_history ORDER BY timestamp DESC LIMIT 30')
      .all();
    regime_history = (result.results || []).map((r: any) => ({
      timestamp: r.timestamp,
      regime: r.regime as CapitalRegime,
      confidence: r.confidence,
    }));
  } catch { /* D1 not initialized yet */ }

  // Transition probability matrix (simplified — based on current regime)
  const transition_probability = computeTransitionProbability(regime);

  // Log regime observation (non-blocking)
  ctx.waitUntil(logRegimeObservation(env, regime, confidence, macro));

  const response: RegimeResponse = {
    current_regime: regime,
    regime_history,
    transition_probability,
    oracle,
    timestamp: new Date().toISOString(),
  };

  return jsonResponse(response);
}

/**
 * GET /api/backtest-lite — Simplified backtest with historical scenarios
 */
async function handleBacktestLite(env: Env, url: URL): Promise<Response> {
  const seedParam = url.searchParams.get('seed');
  const seed = seedParam ? parseInt(seedParam, 10) : 42;
  const modeParam = url.searchParams.get('mode') || 'MODERATE';
  const mode = ['CONSERVATIVE', 'MODERATE', 'AGGRESSIVE'].includes(modeParam) ? modeParam as any : 'MODERATE';

  // Use seeded PRNG for deterministic backtest
  const rng = mulberry32(seed);

  // Simplified backtest with 8 historical scenarios
  const scenarios = getHistoricalScenarios();
  const results = scenarios.map(scenario => {
    const engineOutput = runX10Engine(scenario.macro, mode, 2000);
    const predictedRegime = classifyRegime(scenario.macro).regime;
    const regimeCorrect = predictedRegime === scenario.actualRegime;
    return {
      id: scenario.id,
      label: scenario.label,
      predicted_regime: predictedRegime,
      actual_regime: scenario.actualRegime,
      regime_correct: regimeCorrect,
      predicted_return: engineOutput.risk_metrics.expectedReturn30d,
      actual_return: scenario.actualReturn,
      confidence: engineOutput.confidence_score,
    };
  });

  const regimeAccuracy = results.filter(r => r.regime_correct).length / results.length;

  const response = {
    seed,
    mode,
    total_scenarios: results.length,
    regime_accuracy: Math.round(regimeAccuracy * 100) / 100,
    results,
    disclaimer: 'BACKTEST RESULTS ARE HYPOTHETICAL. Historical macro states are model-constructed, not observed. Past performance does not guarantee future results.',
    timestamp: new Date().toISOString(),
  };

  return jsonResponse(response);
}

// ============================================================================
// TRANSITION PROBABILITY (simplified Markov model)
// ============================================================================

function computeTransitionProbability(currentRegime: CapitalRegime): Record<CapitalRegime, number> {
  const transitions: Record<CapitalRegime, Record<CapitalRegime, number>> = {
    CRISIS:           { CRISIS: 0.40, HIGH_VOL: 0.35, NORMAL: 0.15, CARRY_FAVORABLE: 0.10 },
    HIGH_VOL:         { CRISIS: 0.20, HIGH_VOL: 0.40, NORMAL: 0.30, CARRY_FAVORABLE: 0.10 },
    NORMAL:           { CRISIS: 0.05, HIGH_VOL: 0.15, NORMAL: 0.55, CARRY_FAVORABLE: 0.25 },
    CARRY_FAVORABLE:  { CRISIS: 0.03, HIGH_VOL: 0.07, NORMAL: 0.30, CARRY_FAVORABLE: 0.60 },
  };
  return transitions[currentRegime] || transitions.NORMAL;
}

