// ============================================================================
// D1 LOGGING (non-blocking via ctx.waitUntil)
// ============================================================================

async function logMacroSnapshot(env: Env, macro: any, regime: string, confidence: number): Promise<void> {
  try {
    await env.ORACLE_DB.prepare(`
      INSERT INTO macro_snapshots (id, source, data_label, mep_rate, official_rate, mep_gap,
        inflation_monthly, inflation_expected30d, bcra_policy_rate, money_market_tna,
        plazo_fijo_tna, plazo_fijo_uva_premium, lecaps_tna, badlar_tna, leliq_tna,
        cer_index, cer_monthly_change, crawling_peg, real_data_pct, staleness_hours)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `).bind(
      `MS-${Date.now()}`, 'worker', macro.source, macro.mep.rate, macro.mep.officialRate, macro.mep.gap,
      macro.inflation.monthly, macro.inflation.expected30d, macro.rates.bcraPolicy, macro.rates.moneyMarket,
      macro.rates.plazoFijo, macro.rates.plazoFijoUVA, macro.rates.lecaps, macro.rates.badlar, macro.rates.leliq,
      macro.cer.index, macro.cer.monthlyChange, macro.crawlingPeg, macro.realDataPct, 0
    ).run();
  } catch { /* D1 not initialized — non-critical */ }
}

async function logDecision(env: Env, output: any, mode: string, capital: number): Promise<void> {
  try {
    await env.ORACLE_DB.prepare(`
      INSERT INTO decisions_log (id, decision_type, severity, summary, action, reasoning_json,
        context_json, data_quality, confidence, regime, active_directives_json)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `).bind(
      `DEC-${Date.now()}`, 'ALLOCATION_COMPUTED', 'info',
      `X10 allocation: mode=${mode}, capital=$${capital}`,
      `Computed allocation with ${output.portfolio_allocation.length} positions`,
      JSON.stringify([`Mode: ${mode}`, `Confidence: ${output.confidence_score}`, `Regime: ${output.signalLayer.regime.regime}`]),
      JSON.stringify({ dataAgeMinutes: output.dataLayer.dataAgeMinutes, realDataPct: output.dataLayer.realDataPct }),
      output.dataLayer.macroSource, output.confidence_score, output.signalLayer.regime.regime,
      JSON.stringify(Object.entries(output.x10Directives).filter(([, v]: any) => v.active).map(([k]: any) => k))
    ).run();
  } catch { /* D1 not initialized — non-critical */ }
}

async function logRegimeObservation(env: Env, regime: CapitalRegime, confidence: number, macro: any): Promise<void> {
  try {
    await env.ORACLE_DB.prepare(`
      INSERT INTO regime_history (id, regime, confidence, data_quality, mep_rate, inflation_monthly, bcra_policy_rate)
      VALUES (?, ?, ?, ?, ?, ?, ?)
    `).bind(
      `RH-${Date.now()}`, regime, confidence, macro.source,
      macro.mep.rate, macro.inflation.monthly, macro.rates.bcraPolicy
    ).run();
  } catch { /* D1 not initialized — non-critical */ }
}

// ============================================================================
// HELPERS
// ============================================================================

function corsHeaders(): Record<string, string> {
  return {
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type, Authorization',
  };
}

function jsonResponse(data: unknown, status: number = 200): Response {
  return new Response(JSON.stringify(data, null, 2), {
    status,
    headers: {
      'Content-Type': 'application/json',
      ...corsHeaders(),
    },
  });
}
